from functools import wraps
from time import perf_counter

def timed(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        start = perf_counter()
        try:
            return fn(*args, **kwargs)
        finally:
            print(f'{fn.__name__}: {perf_counter()-start:.3f}s')
    return wrapper

@timed
def total(values):
    return sum(values)

